// 卡内「创作者备注」（creatorNotes）里也写了署名、许可链接和「已翻译改编」声明；BY-SA 卡注明改编版同样以 CC BY-SA 4.0 发布。
// 约束同第一批：不收同人 / 现有 IP / 真人；所有角色均为成年人；不含露骨内容（nsfw 一律 false）。
import type { PlazaSeed } from './plaza-seeds';

type License = 'CC BY 4.0' | 'CC BY-SA 4.0' | 'CC0 1.0';

const LICENSE_URL: Record<License, string> = {
  'CC BY 4.0': 'https://creativecommons.org/licenses/by/4.0/',
  'CC BY-SA 4.0': 'https://creativecommons.org/licenses/by-sa/4.0/',
  'CC0 1.0': 'https://creativecommons.org/publicdomain/zero/1.0/',
};

/** 署名 + 许可 + 改动说明（中英各一段），写进 card_fields.creatorNotes */
function credit(o: { title: string; author: string; url: string; license: License; removedZh?: string; removedEn?: string }): string {
  const lic = `${o.license}，${LICENSE_URL[o.license]}`;
  const removedZh = o.removedZh ?? '删去了原卡的状态栏、脚本与世界书';
  const removedEn = o.removedEn ?? 'original status panels, scripts and lorebook removed';
  const cc0Zh = o.license === 'CC0 1.0' ? '原作者以 CC0 将其贡献至公有领域，本站仍署名致谢。' : '';
  const saZh = o.license === 'CC BY-SA 4.0' ? '本改编版本同样以 CC BY-SA 4.0 发布。' : '';
  const saEn = o.license === 'CC BY-SA 4.0' ? ' This adaptation is likewise released under CC BY-SA 4.0.' : '';
  return (
    `改编自 ${o.author}《${o.title}》（${o.url} ，${lic}）。${cc0Zh}` +
    `本站已翻译改编：译为中文并压缩改写了简介、开场白和设定，${removedZh}；改动由本站负责，不代表原作者。${saZh}\n` +
    `Adapted from "${o.title}" by ${o.author} (${o.url}), ${o.license}. Translated into Chinese and condensed; ${removedEn}.${saEn}`
  );
}

const FV_REPO = 'https://github.com/foreverse-app/character-card-skills/tree/main/';
const fv = (title: string, path: string) =>
  credit({ title, author: 'Foreverse Team', url: FV_REPO + path, license: 'CC BY 4.0', removedZh: '删去了原卡的 HTML 面板、指令与世界书', removedEn: 'original HTML panels, commands and lorebook removed' });
const risu = (title: string, author: string, uuid: string, license: License) =>
  credit({ title, author, url: `https://realm.risuai.net/character/${uuid}`, license });

